$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); $memoryProcessStartup=New-CimInstance -ClassName Win32_ProcessStartup -ClientOnly -Property @{ShowWindow=[uint16]0}; $memoryCommand='"'+$memoryPs+'" -NoProfile -NonInteractive -WindowStyle Hidden -File "'+(Join-Path $PSScriptRoot 'service_entry.ps1')+'"'; $memoryLaunch=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine=$memoryCommand;ProcessStartupInformation=$memoryProcessStartup}; if ($memoryLaunch.ReturnValue -ne 0) { throw 'Native service-host launcher failed.' }
